test('vatSummary with single VAT rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].rate, 10);
  assert.equal(r.value[0].base, 10000);
  assert.equal(r.value[0].vat, 1000);
});

test('vatSummary with multiple VAT rates', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 },
        { sku: 'BRAND-BOOK', name: 'Brand Book', qty: 1, unitPrice: 20000, vatRate: 20, discountPercent: 0 },
      ],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 2);
});

test('vatSummary sorts by rate descending (high to low)', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 },
        { sku: 'BRAND-BOOK', name: 'Brand Book', qty: 1, unitPrice: 20000, vatRate: 20, discountPercent: 0 },
        { sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 5000, vatRate: 5, discountPercent: 0 },
      ],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value[0].rate, 20);
  assert.equal(r.value[1].rate, 10);
  assert.equal(r.value[2].rate, 5);
});

test('vatSummary excludes draft invoices', () => {
  const invoices = [
    {
      status: 'draft',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('vatSummary includes issued invoices', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 1);
});

test('vatSummary includes partially_paid invoices', () => {
  const invoices = [
    {
      status: 'partially_paid',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 1);
});

test('vatSummary includes paid invoices', () => {
  const invoices = [
    {
      status: 'paid',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 1);
});

test('vatSummary calculates base as line amount after discount', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 20 }],
    },
  ];
  const r = vatSummary(invoices);

  // lineTotal = 10000
  // lineDiscount = 10000 * 20 / 100 = 2000
  // lineBase = 10000 - 2000 = 8000
  assert.equal(r.value[0].base, 8000);
});

test('vatSummary calculates VAT on base after discount', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 20 }],
    },
  ];
  const r = vatSummary(invoices);

  // lineBase = 8000
  // lineVat = 8000 * 10 / 100 = 800
  assert.equal(r.value[0].vat, 800);
});

test('vatSummary aggregates multiple lines with same rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 },
        { sku: 'BRAND-BOOK', name: 'Brand Book', qty: 1, unitPrice: 5000, vatRate: 10, discountPercent: 0 },
      ],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].rate, 10);
  assert.equal(r.value[0].base, 15000);
  assert.equal(r.value[0].vat, 1500);
});

test('vatSummary aggregates across multiple invoices', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
    {
      status: 'issued',
      lines: [{ sku: 'BRAND-BOOK', name: 'Brand Book', qty: 1, unitPrice: 5000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].base, 15000);
  assert.equal(r.value[0].vat, 1500);
});

test('vatSummary with zero VAT rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].rate, 0);
  assert.equal(r.value[0].base, 10000);
  assert.equal(r.value[0].vat, 0);
});

test('vatSummary with mixed zero and non-zero rates', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 0 },
        { sku: 'BRAND-BOOK', name: 'Brand Book', qty: 1, unitPrice: 20000, vatRate: 10, discountPercent: 0 },
      ],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 2);
  assert.equal(r.value[0].rate, 10);
  assert.equal(r.value[1].rate, 0);
});

test('vatSummary returns empty array when no invoices', () => {
  const invoices = [];
  const r = vatSummary(invoices);

  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('vatSummary returns empty array when only draft invoices', () => {
  const invoices = [
    {
      status: 'draft',
      lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 10000, vatRate: 10, discountPercent: 0 }],
    },
  ];
  const r = vatSummary(invoices);

  assert.equal(r.value.length, 0);
});

test('vatSummary with complex invoices (multiple lines, discount, VAT)', () => {
  const invoices = [
