      ],
    },
  ];
  const r = vatSummary(invoices);

  // Line 1: lineTotal = 20000, discount = 1000, base = 19000, vat = 1900
  // Line 2: lineTotal = 30000, discount = 3000, base = 27000, vat = 5400
  assert.equal(r.value.length, 2);
  assert.equal(r.value[0].rate, 20);
  assert.equal(r.value[0].base, 27000);
  assert.equal(r.value[0].vat, 5400);
  assert.equal(r.value[1].rate, 10);
  assert.equal(r.value[1].base, 19000);
  assert.equal(r.value[1].vat, 1900);
});

